  function sync(){indicator();faults.querySelector('[data-fault-reviewed]').value='1';payload.value=JSON.stringify([...list.children].map(card=>Object.fromEntries([...card.querySelectorAll('[data-rule]')].map(field=>[field.dataset.rule,field.type==='checkbox'?field.checked:field.value]))));payload.dispatchEvent(new Event('input',{bubbles:true}));}
