  function display(card){const rule=read(card);card.querySelectorAll('[data-rule-counter]').forEach(counter=>{const field=card.querySelector('[data-rule="'+counter.dataset.ruleCounter+'"]');counter.textContent=field.value.length+'/'+field.maxLength;});const names={above:'>',below:'<',at_or_above:'≥',at_or_below:'≤',equals:'=',not_equals:'≠'};card.querySelector('[data-rule-title]').textContent=rule.name||'New Fault';const status=card.querySelector('[data-rule-status]');status.textContent=rule.enabled?'Enabled':'Disabled';status.classList.toggle('enabled',!!rule.enabled);card.querySelector('[data-rule-enabled-label]').textContent=status.textContent;card.querySelectorAll('[data-rule-preview]').forEach(cell=>{const key=cell.dataset.rulePreview;cell.textContent=key==='condition'?names[rule.condition]:key==='threshold'?(rule.threshold===''?'Not configured':rule.threshold):(rule[key]||'—');if(key==='severity'){cell.dataset.severity=rule.severity;cell.textContent=({Information:'Info',Warning:'Warn'})[rule.severity]||rule.severity;}});}
